class VersionedStore {
  constructor() {
    this.history = new Map()
  }

  set(key, value, t) {
    if (!this.history.has(key)) this.history.set(key, { times: [], values: [] })
    const entry = this.history.get(key)
    entry.times.push(t)
    entry.values.push(value)
  }

  get(key, t) {
    const entry = this.history.get(key)
    if (!entry) return ''
    let lo = 0
    let hi = entry.times.length
    while (lo < hi) {
      const mid = (lo + hi) >> 1
      if (entry.times[mid] <= t) lo = mid + 1
      else hi = mid
    }
    return lo === 0 ? '' : entry.values[lo - 1]
  }
}

function runVersionedStore(ops) {
  const store = new VersionedStore()
  return ops.map(op => (op[0] === 'set' ? (store.set(op[1], op[2], op[3]), null) : store.get(op[1], op[2])))
}

